html='''<!DOCTYPE html><html lang="kk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#6b43df"><title>My English Word Lab — Grade 4</title><style>
*{box-sizing:border-box}body{margin:0;background:#f8f7fc;color:#25223c;font-family:system-ui,-apple-system,Segoe UI,sans-serif}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #eb9d22;outline-offset:4px}header{background:white;border-bottom:1px solid #eeeaf5}.top{max-width:1240px;margin:auto;padding:20px 28px;display:flex;align-items:center;gap:12px}.logo{background:#6b43df;color:white;padding:9px;border-radius:14px;font-size:24px}.brand{font-weight:850;font-size:19px}.grade{margin-left:auto;background:#f2ecff;color:#6840c6;border-radius:30px;padding:8px 16px;font-weight:750;font-size:13px}main{max-width:1240px;padding:28px;margin:auto}.hero{background:#7048e8;border-radius:30px;padding:36px 40px;color:white;display:flex;justify-content:space-between;overflow:hidden;position:relative}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:800;color:#e2d8ff}h1{font-size:clamp(32px,5vw,52px);line-height:1.1;letter-spacing:-2px;margin:15px 0}.hero p{color:#eee7ff;margin-bottom:22px}.pills{display:flex;gap:8px;flex-wrap:wrap}.pills span{padding:8px 13px;background:#ffffff20;border:1px solid #ffffff30;border-radius:20px;font-size:13px}.art{min-width:240px;position:relative;display:grid;place-items:center}.planet{font-size:95px;background:#9b7af3;border-radius:50%;width:185px;height:185px;display:grid;place-items:center;transform:rotate(-10deg)}.bubble{position:absolute;background:#ffdc75;color:#493926;padding:12px 22px;border-radius:18px;font-weight:800;transform:rotate(8deg);right:-8px;top:0}.bubble.bottom{top:auto;bottom:0;left:-20px;right:auto;background:#b4f4d8;transform:rotate(-8deg)}.sectionline{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:30px 0 14px}.sectionline h2{font-size:23px;margin:0}.muted{color:#79758b;font-size:14px}.units{display:flex;gap:10px;overflow-x:auto;padding:5px 2px 15px;scrollbar-width:thin}.unit{min-width:108px;border:1px solid #e7e2f1;background:white;border-radius:17px;padding:14px;text-align:left;color:#625d76;white-space:nowrap}.unit strong{display:block;color:#2f2844;margin-bottom:5px}.unit.active{background:#6b43df;color:#e8ddff;border-color:#6b43df;box-shadow:0 6px 14px #7048e82a}.unit.active strong{color:white}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0 22px}.search{flex:1;min-width:220px;position:relative}.search input{width:100%;padding:14px 18px;border:1px solid #e5e0ef;border-radius:14px;background:white}.control{border:1px solid #e5e0ef;background:white;border-radius:14px;padding:12px 16px;color:#55486e}.control.on{background:#ede5ff;border-color:#b5a0e8;color:#5831b0}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:17px}.card{background:white;border:1px solid #ebe6f4;border-radius:22px;overflow:hidden;transition:transform .2s,box-shadow .2s}.card:hover{transform:translateY(-4px);box-shadow:0 12px 30px #493b7310}.visual{height:140px;position:relative;display:grid;place-items:center;background:var(--bg);font-size:61px}.symbol{filter:drop-shadow(0 8px 0 #ffffff70)}.number{position:absolute;left:13px;top:12px;font-size:11px;color:#544e65;background:#ffffffb0;border-radius:20px;padding:4px 8px;font-weight:700}.save{position:absolute;right:12px;top:10px;border:0;width:32px;height:32px;border-radius:50%;background:white;color:#ada4be;font-size:17px}.save.yes{background:#4a2e93;color:white}.body{padding:18px}.en{font-size:19px;line-height:1.3;font-weight:800;min-height:25px;margin-bottom:9px;overflow-wrap:anywhere}.translation{border:0;padding:0;background:transparent;text-align:left;color:#6c617e;min-height:44px;font-size:14px;line-height:1.45;width:100%}.translation.masked{color:#734dcc;font-size:13px}.foot{display:flex;justify-content:space-between;align-items:center;margin-top:12px;border-top:1px solid #f2eef7;padding-top:12px}.foot small{color:#a49bb4;font-size:10px;letter-spacing:1px}.audio{border:0;background:#f1ecfb;color:#6745bb;border-radius:10px;padding:6px 10px}.empty{grid-column:1/-1;text-align:center;padding:50px;background:white;border-radius:20px}footer{text-align:center;font-size:12px;color:#90879e;padding:30px 15px}.progress{display:flex;gap:12px;align-items:center}.track{width:100px;height:7px;background:#e6dff2;border-radius:10px;overflow:hidden}.fill{height:100%;background:#6b43df}#notice{font-size:13px;color:#694394;min-height:18px}@media(max-width:980px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.art{min-width:190px}}@media(max-width:700px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}main{padding:16px}.top{padding:15px 16px}.brand{font-size:15px}.grade{padding:6px 10px}.hero{padding:26px}.art{display:none}.hero p{font-size:14px}.sectionline{flex-wrap:wrap}.body{padding:14px}.en{font-size:17px}.visual{height:120px}.control{font-size:13px}.track{width:60px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{header,.hero,.units,.tools,.save,.audio,footer,#notice{display:none}.grid{grid-template-columns:repeat(3,1fr)}.card{break-inside:avoid}.visual{height:80px;font-size:42px}}
</style></head><body><header><div class="top"><div class="logo">✦</div><div class="brand">My English Word Lab</div><span class="grade">GRADE 4</span></div></header><main><section class="hero"><div><div class="eyebrow">ENGLISH + ҚАЗАҚША</div><h1>Small words.<br>Big discoveries.</h1><p>Сөздер әлемін аш. Оқы, тыңда, есте сақта!</p><div class="pills"><span>📚 8 unit</span><span>✨ 211 сөз бен тіркес</span><span>🇰🇿 Қазақша аударма</span></div></div><div class="art" aria-hidden="true"><div class="planet">🔬</div><div class="bubble">Hello! 👋</div><div class="bubble bottom">Сәлем! ✨</div></div></section><div class="sectionline"><h2>Choose your unit</h2><span class="muted">Бөлімді таңда →</span></div><nav class="units" id="units" aria-label="Бөлімдер"></nav><div class="sectionline"><div><h2 id="heading"></h2><span class="muted" id="count"></span></div><div class="progress"><span class="muted" id="progress"></span><div class="track"><div id="fill" class="fill"></div></div></div></div><div class="tools"><div class="search"><input id="search" placeholder="🔎  English / Қазақша — сөз іздеу" aria-label="Барлық бөлімнен сөз іздеу"></div><button class="control" id="hide">◉ Аударманы жасыру</button><button class="control" id="learned">✓ Жаттаған сөздер</button></div><p id="notice" role="status"></p><div class="grid" id="grid"></div><footer>My English Word Lab · Grade 4 · English — Қазақша<br>Сөздер мен аудармалар жүктелген сөздік бойынша берілген.</footer></main><script>
const DATA=__DATA__;
let unit=0,hidden=false,onlyLearned=false,saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('wordlab-grade4-v1')||'[]'))}catch{}
const $=id=>document.getElementById(id),colors=['#fff0cd','#eae1ff','#dcf4ef','#ffe1e9','#dfeeff','#f6e3fd'];
function save(){try{localStorage.setItem('wordlab-grade4-v1',JSON.stringify([...saved]))}catch{$('notice').textContent='Бұл браузерде белгілерді сақтау мүмкін емес.'}}
DATA.forEach((u,i)=>{let b=document.createElement('button');b.className='unit';b.innerHTML='<strong>'+u.name.replace('Module','Unit')+'</strong>'+u.words.length+' сөз';b.onclick=()=>{unit=i;$('search').value='';render()};$('units').append(b)});
function speak(word){if(!('speechSynthesis' in window)){$('notice').textContent='Бұл браузер дыбыстауды қолдамайды.';return}speechSynthesis.cancel();let s=new SpeechSynthesisUtterance(word);s.lang='en-GB';s.rate=.8;s.onerror=()=>{$('notice').textContent='Дыбыс қолжетімсіз. Құрылғының ағылшын дауысын тексеріңіз.'};speechSynthesis.speak(s)}
function render(){document.querySelectorAll('.unit').forEach((b,i)=>{b.classList.toggle('active',i===unit);b.setAttribute('aria-pressed',i===unit)});let q=$('search').value.trim().toLocaleLowerCase();let rows=[];DATA.forEach((u,ui)=>u.words.forEach((w,wi)=>{let id=ui+':'+wi;if((q?w.slice(0,2).some(t=>t.toLocaleLowerCase().includes(q)):ui===unit)&&(!onlyLearned||saved.has(id)))rows.push({w,id,ui,wi})}));$('heading').textContent=q?'Іздеу нәтижелері':DATA[unit].name.replace('Module','Unit');$('count').textContent=rows.length+' сөз / сөз тіркесі'+(q?' · барлық бөлімдерден':'');let n=DATA[unit].words.filter((w,i)=>saved.has(unit+':'+i)).length;$('progress').textContent=n+' / '+DATA[unit].words.length+' жатталды';$('fill').style.width=n/DATA[unit].words.length*100+'%';$('grid').replaceChildren();$('hide').textContent=hidden?'◉ Аударманы көрсету':'◉ Аударманы жасыру';$('hide').classList.toggle('on',hidden);$('hide').setAttribute('aria-pressed',hidden);$('learned').classList.toggle('on',onlyLearned);$('learned').setAttribute('aria-pressed',onlyLearned);
rows.forEach(({w,id,ui,wi})=>{let card=document.createElement('article');card.className='card';card.style.setProperty('--bg',colors[wi%colors.length]);card.innerHTML='<div class="visual"><span class="number"></span><span class="symbol" aria-hidden="true"></span><button class="save" title="Жаттадым"></button></div><div class="body"><div class="en" lang="en"></div><button class="translation" lang="kk"></button><div class="foot"><small>ENGLISH → ҚАЗАҚША</small><button class="audio">🔊</button></div></div>';card.querySelector('.number').textContent=q?DATA[ui].name.replace('Module','Unit'):String(wi+1).padStart(2,'0');card.querySelector('.symbol').replaceWith(photoForWord(w));card.querySelector('.en').textContent=w[0];let tr=card.querySelector('.translation');tr.textContent=hidden?'Аударманы ашу ↗':w[1];tr.classList.toggle('masked',hidden);tr.onclick=()=>{tr.textContent=w[1];tr.classList.remove('masked')};let b=card.querySelector('.save');b.textContent=saved.has(id)?'✓':'☆';b.classList.toggle('yes',saved.has(id));b.setAttribute('aria-label',w[0]+' — жаттадым');b.setAttribute('aria-pressed',saved.has(id));b.onclick=()=>{saved.has(id)?saved.delete(id):saved.add(id);save();render()};let a=card.querySelector('.audio');a.setAttribute('aria-label',w[0]+' — тыңдау');a.onclick=()=>speak(w[0]);$('grid').append(card)});if(!rows.length){let e=document.createElement('div');e.className='empty';e.textContent=onlyLearned?'Әзірге белгіленген сөз жоқ. ☆ батырмасымен сөздерді белгіле.':'Сөз табылмады. Басқа сөз жазып көр.';$('grid').append(e)}}
$('search').oninput=render;$('hide').onclick=()=>{hidden=!hidden;render()};$('learned').onclick=()=>{onlyLearned=!onlyLearned;render()};render();
</script></body></html>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False))
(p/'dist/index.html').write_text(html)
m=json.loads((p/'.openai/hosting.json').read_text());m['static']={'directory':'dist'};(p/'.openai/hosting.json').write_text(json.dumps(m))
print('Built',sum(len(u['words']) for u in data),'bilingual cards')

