s=s.replace('</body>', '<script src="game.js"></script></body>')
h.write_text(s)
for f in ['photos.js','game.js']:shutil.copyfile(p/f,p/'dist'/f)
for f in (p/'assets').glob('*.png'):shutil.copyfile(f,p/'dist/assets'/f.name)

